using CCAP.Application.Abstractions.Persistence;using CCAP.Domain.Entities;using MediatR;using System.Text.Json;
namespace CCAP.Application.Features.Patients.Commands.AddCareLog;
public sealed class AddCareLogCommandHandler:IRequestHandler<AddCareLogCommand,Guid>{private readonly IPatientRepository _patients;private readonly IPatientCareLogRepository _logs;private readonly IPatientAuditLogRepository _audit;private readonly IUnitOfWork _uow;public AddCareLogCommandHandler(IPatientRepository p,IPatientCareLogRepository l,IPatientAuditLogRepository a,IUnitOfWork u){_patients=p;_logs=l;_audit=a;_uow=u;}public async Task<Guid> Handle(AddCareLogCommand r,CancellationToken ct){var p=await _patients.GetByIdForWorkflowUpdateAsync(r.PatientId,ct)??throw new KeyNotFoundException("Patient not found.");var log=new PatientCareLog(r.PatientId,r.RecordedByUserId,r.LogType,r.Item,r.Quantity,r.Unit,r.Notes);await _logs.AddAsync(log,ct);p.Activities.Add(new Activity(p.PatientId,r.RecordedByUserId,"Care","Care log recorded",$"{r.LogType}: {r.Item}"));await _audit.AddAsync(new PatientAuditLog(p.PatientId,r.RecordedByUserId,"PatientCareLog",log.PatientCareLogId.ToString(),"CREATE",null,JsonSerializer.Serialize(new{r.LogType,r.Item,r.Quantity,r.Unit,r.Notes}),"Care log created."),ct);await _uow.SaveChangesAsync(ct);return log.PatientCareLogId;}}
